// What a command line asks the gate for.
export type Options = {
  max: number
  reuse: boolean
  all: boolean
  paths: string[]
}

export const DEFAULT_GATE = 10

const gateFrom = (value: string | undefined): number => {
  const max = Number(value)
  if (Number.isNaN(max)) {
    throw new Error(`--max wants a number, got ${value ?? 'nothing'}`)
  }
  return max
}

export function readOptions(argv: string[]): Options {
  const options: Options = { max: DEFAULT_GATE, reuse: false, all: false, paths: [] }
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index]
    if (argument === '--max') {
      index += 1
      options.max = gateFrom(argv[index])
    } else if (argument === '--reuse') {
      options.reuse = true
    } else if (argument === '--all') {
      options.all = true
    } else if (argument.startsWith('-')) {
      throw new Error(`unknown option ${argument}`)
    } else {
      options.paths.push(argument.replace(/\/+$/, ''))
    }
  }
  return options
}

// A path argument names a file or a directory to gate; without any, the gate
// covers every measured file.
export const isGated = (file: string, paths: string[]): boolean =>
  paths.length === 0 || paths.some((path) => file === path || file.startsWith(`${path}/`))

scripts/mutation-reuse/fingerprint.ts.source:
// What a recorded mutation result depends on, reduced to one string: the files
// its manifest cannot see for itself, and what they held.
//
// Listing a directory is the caller's, because what a listing means differs
// between the runners. Which of its entries the fingerprint covers is decided
// here: a fingerprint that leaves out a file it claims to cover reads as
// unchanged while that file changes underneath it, which is the defect this
// module exists to keep out.
import { createHash } from 'node:crypto'
import { join } from 'node:path'

export type FileSelection = {
  directory: string
  suffix: string
  without?: string
}

export type NamedContent = {
  path: string
  content: string
}

const isSelected = (entry: string, { suffix, without }: FileSelection): boolean =>
  entry.endsWith(suffix) && (without === undefined || !entry.endsWith(without))

export const selectedFiles = (
  selections: FileSelection[],
  listing: (directory: string) => string[],
): string[] =>
  selections.flatMap((selection) =>
    listing(selection.directory)
      .filter((entry) => isSelected(entry, selection))
      .map((entry) => join(selection.directory, entry)))

// Path and content both go in, so a renamed file moves the fingerprint even
// when nothing was edited, and the paths are sorted so the order the caller
// listed them in cannot change the answer.
//
// `acceptance/generator.ts` computes the same digest over the files it
// generates, and the two are deliberately not one function. That one is the
// `implementation_hash` the generator writes into a metadata document and
// gherkin-mutator reads back: it is part of an agreement with a tool outside
// this project, and changing it invalidates records the tool wrote. This one is
// read only by the runner that wrote it, against a stamp in `.mutation/`, and
// is free to widen whenever a stamp should cover more. Sharing the digest would
// tie an external contract to an internal convenience, so that a change made
// for one would silently move the other.
export const fingerprint = (files: NamedContent[]): string => {
  const digest = createHash('sha256')
  for (const file of [...files].sort((left, right) => left.path.localeCompare(right.path))) {
    digest.update(`${file.path}\0${file.content}\0`)
  }
  return `sha256:${digest.digest('hex')}`
}

scripts/mutation-reuse/stamp.ts.source:
// The stamp a mutation runner writes beside its manifest, and what it takes to
// believe one.
//
// A runner reuses recorded results only while the fingerprint it stamped still
// matches the project in front of it. Everything about that record is here: the
// field it is written under, the version that field is read at, when a stamp
// counts as a match, and when a run has earned the right to write one.

export type Stamp = {
  field: string
  version: number
}

// One stamp per runner. The version travels with the field, so widening what a
// fingerprint covers is a version bump away from re-testing everything once,
// rather than reusing results the new fingerprint was never compared against.
export const ACCEPTANCE_IMPLEMENTATION: Stamp = { field: 'implementation_hash', version: 1 }
export const MUTATION_TIER: Stamp = { field: 'tier_hash', version: 1 }

const claimedHash = (stamp: Stamp, recorded: string): string | undefined => {
  const claim: Record<string, unknown> = JSON.parse(recorded)
  const hash = claim[stamp.field]
  return claim.version === stamp.version && typeof hash === 'string' ? hash : undefined
}

// No stamp yet, a stamp from another version of this runner, and a stamp
// missing the hash it was supposed to carry all mean the same thing: nothing
// recorded describes the project in front of us, so nothing may be reused.
export const resultsAreReusable = (
  stamp: Stamp,
  recorded: string | undefined,
  current: string,
): boolean => recorded !== undefined && claimedHash(stamp, recorded) === current

export const stampText = (stamp: Stamp, hash: string): string =>
  `${JSON.stringify({ version: stamp.version, [stamp.field]: hash }, null, 2)}\n`

// A runner rewrites its manifest whether the mutants survived or not, so a
// stamp follows a red run as readily as a green one. What must not be stamped
// is a run that never reached a verdict: a runner that could not be spawned, or
// that died on a signal, can leave a partial manifest behind, and stamping that
// would claim results this fingerprint never earned. `null` is the exit status
// of a process that did not exit on its own.
export const reachedVerdict = (statuses: (number | null)[]): boolean =>
  statuses.every((status) => status !== null)

